from taf.internal.core import NamedComponentFactory
from taf.converters.base import FilePatternFinder
from taf.sw.dcap.rd.facade import DcapConnection
from .converter import (EmilConverterForSource, EmilConverterForCalls, EmilConverterForCall,
                        JsonOutputStrategy, CsvOutputStrategy)


class EmilConverterFactoryBase(NamedComponentFactory):
    _optional_parameters = {"output_directory", "server_filter", "client_filter",
                            "uploading_timeout", "decoding_timeout"}

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(EmilConverterFactoryBase, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        dcap = configuration["dcap"] if "dcap" in configuration else {}
        default_dcap = {"host": "127.0.0.1", "port": 9443, "secure": True,
                        "username": None, "password": None}
        default_dcap.update(dcap)
        resulting_arguments["dcap_connection"] = DcapConnection(**default_dcap)
        resulting_arguments["finder"] = FilePatternFinder(
            file_path_pattern=configuration["file_path_pattern"])
        resulting_arguments["decoding_strategy"] = CsvOutputStrategy() \
            if configuration.get("output_type", "json").lower() == "csv" else JsonOutputStrategy()


class EmilConverterForSourceFactory(EmilConverterFactoryBase):
    _product_class = EmilConverterForSource


class EmilConverterForCallsFactory(EmilConverterFactoryBase):
    _product_class = EmilConverterForCalls


class EmilConverterForCallFactory(EmilConverterFactoryBase):
    _product_class = EmilConverterForCall
    _mandatory_parameters = {"trace_id"}
